import React, { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Avatar,
  Box,
  Button,
  Chip,
  InputAdornment,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
  alpha,
  useTheme,
} from "@mui/material";
import {
  CheckCircleOutline,
  Download,
  HourglassEmpty,
  Paid,
  ReceiptLong,
  Search,
  Visibility,
} from "@mui/icons-material";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import axiosInstance from "../utils/axiosConfig";

const formatMoney = (value) =>
  `₹${Number(value || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 })}`;

const formatDate = (value) => {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "-";
  return date.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
};

const getName = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(" ").trim() || user?.email || "Employee";

const getInitials = (name) => {
  if (!name || name === "Employee") return "EM";
  const parts = name.trim().split(" ");
  if (parts.length >= 2) return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
  return name.slice(0, 2).toUpperCase();
};

/* ─── Stat Card Component ──────────────────────────────────────────────────── */
function StatCard({ icon: Icon, value, label, tone = "blue", isDark }) {
  const colors = {
    blue: {
      main: "#2563eb",
      bgDark: "rgba(37, 99, 235, 0.12)",
      bgLight: "#f0f6ff",
      borderDark: "rgba(59, 130, 246, 0.35)",
      borderLight: "#bfdbfe",
      iconBgDark: "rgba(59, 130, 246, 0.25)",
      iconBgLight: "#dbeafe",
      iconColor: "#2563eb",
      textDark: "#93c5fd",
      textLight: "#1d4ed8",
    },
    green: {
      main: "#16a34a",
      bgDark: "rgba(22, 163, 74, 0.12)",
      bgLight: "#f0fdf4",
      borderDark: "rgba(34, 197, 94, 0.25)",
      borderLight: "#bbf7d0",
      iconBgDark: "rgba(34, 197, 94, 0.25)",
      iconBgLight: "#dcfce7",
      iconColor: "#16a34a",
      textDark: "#86efac",
      textLight: "#15803d",
    },
    amber: {
      main: "#d97706",
      bgDark: "rgba(217, 119, 6, 0.12)",
      bgLight: "#fffbeb",
      borderDark: "rgba(245, 158, 11, 0.3)",
      borderLight: "#fde68a",
      iconBgDark: "rgba(245, 158, 11, 0.25)",
      iconBgLight: "#fef3c7",
      iconColor: "#d97706",
      textDark: "#fde047",
      textLight: "#b45309",
    },
    slate: {
      main: "#64748b",
      bgDark: "rgba(100, 116, 139, 0.12)",
      bgLight: "#f8fafc",
      borderDark: "rgba(148, 163, 184, 0.25)",
      borderLight: "#e2e8f0",
      iconBgDark: "rgba(148, 163, 184, 0.2)",
      iconBgLight: "#f1f5f9",
      iconColor: "#64748b",
      textDark: "#cbd5e1",
      textLight: "#475569",
    },
  };

  const c = colors[tone] || colors.blue;

  return (
    <Paper
      elevation={0}
      sx={{
        p: 2.2,
        borderRadius: 3,
        bgcolor: isDark ? c.bgDark : c.bgLight,
        border: `1px solid ${isDark ? c.borderDark : c.borderLight}`,
        transition: "all 0.25s ease-in-out",
        "&:hover": {
          transform: "translateY(-2px)",
          boxShadow: isDark
            ? `0 8px 24px ${alpha(c.main, 0.25)}`
            : `0 8px 20px ${alpha(c.main, 0.15)}`,
        },
      }}
    >
      <Stack direction="row" spacing={2} alignItems="center">
        <Box
          sx={{
            width: 48,
            height: 48,
            borderRadius: 2.5,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            bgcolor: isDark ? c.iconBgDark : c.iconBgLight,
            color: isDark ? c.textDark : c.iconColor,
            flexShrink: 0,
          }}
        >
          <Icon sx={{ fontSize: 26 }} />
        </Box>
        <Box sx={{ minWidth: 0 }}>
          <Typography
            variant="h4"
            fontWeight={900}
            sx={{
              lineHeight: 1,
              color: isDark ? "#ffffff" : "#0f172a",
              fontSize: { xs: "1.6rem", md: "1.85rem" },
            }}
          >
            {value}
          </Typography>
          <Typography
            variant="body2"
            sx={{
              mt: 0.6,
              fontWeight: 600,
              color: isDark ? c.textDark : c.textLight,
            }}
          >
            {label}
          </Typography>
        </Box>
      </Stack>
    </Paper>
  );
}

/* ─── Main Component ───────────────────────────────────────────────────────── */
export default function Payslips() {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";

  // Design tokens
  const bgMain = isDark ? "#090d16" : "#f8fafc";
  const bgCard = isDark ? "rgba(15, 23, 42, 0.75)" : "#ffffff";
  const bgSubtle = isDark ? "rgba(30, 41, 59, 0.5)" : "#f1f5f9";
  const borderCol = isDark ? "rgba(255, 255, 255, 0.08)" : "rgba(0, 0, 0, 0.08)";
  const textPrimary = isDark ? "#f8fafc" : "#0f172a";
  const textSecondary = isDark ? "#94a3b8" : "#64748b";

  const [payslips, setPayslips] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    setLoading(true);
    axiosInstance
      .get("/payroll/payslips")
      .then(({ data }) => setPayslips(data.result?.payslips || []))
      .catch(() => setPayslips([]))
      .finally(() => setLoading(false));
  }, []);

  const filtered = useMemo(() => {
    const term = search.trim().toLowerCase();
    if (!term) return payslips;
    return payslips.filter((row) =>
      `${getName(row.employee)} ${row.month} ${row.year} ${row.payslipNo || ""}`
        .toLowerCase()
        .includes(term)
    );
  }, [payslips, search]);

  // Stats
  const totalPaid = payslips.filter((s) => s.paymentStatus === "PAID").length;
  const totalPending = payslips.filter((s) => s.paymentStatus !== "PAID").length;
  const totalDisbursed = payslips
    .filter((s) => s.paymentStatus === "PAID")
    .reduce((sum, s) => sum + Number(s.netSalary || 0), 0);

  // PDF download with error handling (Issue 5 fix)
  const downloadPdf = (slip) => {
    try {
      const doc = new jsPDF();
      doc.setFontSize(16);
      doc.text("Vanurtech Pvt Ltd", 14, 18);
      doc.setFontSize(12);
      doc.text(`SALARY SLIP - ${slip.month} ${slip.year}`, 14, 28);
      doc.text(`Employee: ${getName(slip.employee)}`, 14, 40);
      doc.text(`Pay Period: ${formatDate(slip.payPeriodStart)} - ${formatDate(slip.payPeriodEnd)}`, 14, 48);
      autoTable(doc, {
        startY: 58,
        head: [["Earnings", "Amount"]],
        body: (slip.earnings || []).map((item) => [item.name, formatMoney(item.amount)]),
      });
      autoTable(doc, {
        startY: doc.lastAutoTable.finalY + 8,
        head: [["Deductions", "Amount"]],
        body: (slip.deductions || []).map((item) => [item.name, formatMoney(item.amount)]),
      });
      const y = doc.lastAutoTable.finalY + 12;
      doc.setFontSize(12);
      doc.text(`Gross Earnings: ${formatMoney(slip.grossSalary)}`, 14, y);
      doc.text(`Total Deductions: ${formatMoney(slip.totalDeductions)}`, 14, y + 8);
      doc.setFontSize(14);
      doc.text(`NET PAY: ${formatMoney(slip.netSalary)}`, 14, y + 18);
      doc.setFontSize(11);
      doc.text(`Payment Date: ${formatDate(slip.paymentDate)}`, 14, y + 30);
      doc.text(`Payment Mode: ${slip.paymentMethod || "-"}`, 14, y + 38);
      doc.text(`Bank: ${slip.bankName || "-"}`, 14, y + 46);
      doc.text(`Account: ${slip.accountMasked || "-"}`, 14, y + 54);
      doc.save(`${slip.payslipNo || "payslip"}.pdf`);
    } catch (err) {
      console.error("PDF generation error:", err);
      setError("Failed to generate PDF. Please try again or contact support.");
    }
  };

  return (
    <Box
      sx={{
        p: { xs: 2, sm: 3, md: 3.5 },
        bgcolor: bgMain,
        minHeight: "100vh",
        color: textPrimary,
        transition: "background-color 0.3s ease, color 0.3s ease",
      }}
    >
      {/* ── HEADER ────────────────────────────────────────────────────────────── */}
      <Paper
        elevation={0}
        sx={{
          p: { xs: 2.5, md: 3 },
          mb: 3,
          borderRadius: 3.5,
          bgcolor: bgCard,
          border: `1px solid ${borderCol}`,
          backdropFilter: "blur(12px)",
          boxShadow: isDark
            ? "0 10px 30px rgba(0, 0, 0, 0.3)"
            : "0 10px 30px rgba(0, 0, 0, 0.04)",
        }}
      >
        <Stack
          direction={{ xs: "column", md: "row" }}
          alignItems={{ xs: "flex-start", md: "center" }}
          justifyContent="space-between"
          spacing={2.5}
        >
          <Stack direction="row" spacing={1.5} alignItems="center">
            <Avatar
              sx={{
                bgcolor: alpha(theme.palette.primary.main, 0.15),
                color: theme.palette.primary.main,
                width: 48,
                height: 48,
                borderRadius: 2.5,
              }}
            >
              <ReceiptLong sx={{ fontSize: 28 }} />
            </Avatar>
            <Box>
              <Typography
                variant="h4"
                fontWeight={900}
                sx={{
                  letterSpacing: "-0.02em",
                  background: isDark
                    ? "linear-gradient(135deg, #ffffff 0%, #94a3b8 100%)"
                    : "linear-gradient(135deg, #0f172a 0%, #334155 100%)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                }}
              >
                Payslips
              </Typography>
              <Typography variant="body2" sx={{ color: textSecondary, fontWeight: 500 }}>
                View and download finalized monthly salary slips for all employees
              </Typography>
            </Box>
          </Stack>
        </Stack>
      </Paper>

      {/* ── ERROR ALERT ───────────────────────────────────────────────────────── */}
      {error && (
        <Alert
          severity="error"
          onClose={() => setError("")}
          sx={{ mb: 3, borderRadius: 2.5, fontWeight: 600 }}
        >
          {error}
        </Alert>
      )}

      {/* ── STAT CARDS ────────────────────────────────────────────────────────── */}
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "1fr",
            sm: "repeat(2, minmax(0, 1fr))",
            lg: "repeat(4, minmax(0, 1fr))",
          },
          gap: 2.5,
          mb: 3,
        }}
      >
        <StatCard icon={ReceiptLong} value={payslips.length} label="Total Payslips" tone="blue" isDark={isDark} />
        <StatCard icon={CheckCircleOutline} value={totalPaid} label="Paid" tone="green" isDark={isDark} />
        <StatCard icon={HourglassEmpty} value={totalPending} label="Pending" tone="amber" isDark={isDark} />
        <StatCard icon={Paid} value={formatMoney(totalDisbursed)} label="Total Disbursed" tone="slate" isDark={isDark} />
      </Box>

      {/* ── SEARCH BAR ────────────────────────────────────────────────────────── */}
      <Paper
        elevation={0}
        sx={{
          p: 2,
          mb: 3,
          borderRadius: 3,
          bgcolor: bgCard,
          border: `1px solid ${borderCol}`,
          backdropFilter: "blur(12px)",
        }}
      >
        <TextField
          size="small"
          placeholder="Search by employee name, month, payslip #..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <Search sx={{ color: textSecondary, fontSize: 20 }} />
              </InputAdornment>
            ),
          }}
          sx={{
            minWidth: { xs: "100%", sm: 340 },
            "& .MuiOutlinedInput-root": {
              borderRadius: 2.5,
              bgcolor: bgSubtle,
              "& fieldset": { borderColor: borderCol },
            },
          }}
        />
      </Paper>

      {/* ── TABLE ─────────────────────────────────────────────────────────────── */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: 3,
          bgcolor: bgCard,
          border: `1px solid ${borderCol}`,
          overflow: "hidden",
          backdropFilter: "blur(12px)",
          boxShadow: isDark
            ? "0 10px 30px rgba(0, 0, 0, 0.3)"
            : "0 10px 30px rgba(0, 0, 0, 0.04)",
        }}
      >
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow
                sx={{
                  bgcolor: isDark ? "rgba(30, 41, 59, 0.6)" : "#f8fafc",
                  "& .MuiTableCell-head": {
                    fontWeight: 800,
                    fontSize: "0.8rem",
                    textTransform: "uppercase",
                    letterSpacing: "0.06em",
                    color: textSecondary,
                    borderBottom: `1px solid ${borderCol}`,
                    py: 1.8,
                  },
                }}
              >
                <TableCell>Employee</TableCell>
                <TableCell>Period</TableCell>
                <TableCell>Gross</TableCell>
                <TableCell>Deductions</TableCell>
                <TableCell>Net Pay</TableCell>
                <TableCell>Payment Date</TableCell>
                <TableCell>Status</TableCell>
                <TableCell align="right">Action</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={8} align="center" sx={{ py: 6 }}>
                    <Typography color={textSecondary} fontWeight={600}>
                      Loading payslips...
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : filtered.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} align="center" sx={{ py: 6 }}>
                    <Avatar
                      sx={{
                        width: 56,
                        height: 56,
                        mx: "auto",
                        mb: 1.5,
                        bgcolor: alpha(theme.palette.primary.main, 0.1),
                        color: theme.palette.primary.main,
                      }}
                    >
                      <ReceiptLong sx={{ fontSize: 28 }} />
                    </Avatar>
                    <Typography fontWeight={800} color={textPrimary}>
                      No payslips found
                    </Typography>
                    <Typography variant="body2" color={textSecondary} sx={{ mt: 0.5 }}>
                      {search
                        ? "No payslips match your search criteria."
                        : "Payslips will appear here after payroll is processed and paid."}
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : (
                filtered.map((row) => {
                  const name = getName(row.employee);
                  return (
                    <TableRow
                      key={row._id}
                      sx={{
                        transition: "background-color 0.15s ease",
                        "&:hover": {
                          bgcolor: isDark ? "rgba(59, 130, 246, 0.06)" : "rgba(37, 99, 235, 0.04)",
                        },
                        "& .MuiTableCell-root": {
                          borderBottom: `1px solid ${borderCol}`,
                          py: 1.6,
                        },
                      }}
                    >
                      <TableCell>
                        <Stack direction="row" spacing={1.5} alignItems="center">
                          <Avatar
                            sx={{
                              width: 36,
                              height: 36,
                              fontSize: "0.8rem",
                              fontWeight: 800,
                              bgcolor: isDark ? "rgba(59, 130, 246, 0.2)" : "#dbeafe",
                              color: isDark ? "#93c5fd" : "#2563eb",
                            }}
                          >
                            {getInitials(name)}
                          </Avatar>
                          <Box>
                            <Typography fontWeight={800} fontSize="0.875rem" color={textPrimary}>
                              {name}
                            </Typography>
                            <Typography variant="caption" color={textSecondary}>
                              {row.payslipNo || "-"}
                            </Typography>
                          </Box>
                        </Stack>
                      </TableCell>
                      <TableCell>
                        <Typography fontWeight={700} fontSize="0.875rem" color={textPrimary}>
                          {row.month} {row.year}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography fontWeight={700} fontSize="0.875rem" color={textPrimary}>
                          {formatMoney(row.grossSalary)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography fontWeight={700} fontSize="0.875rem" sx={{ color: isDark ? "#f87171" : "#dc2626" }}>
                          -{formatMoney(row.totalDeductions)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography fontWeight={900} fontSize="0.95rem" color={textPrimary}>
                          {formatMoney(row.netSalary)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Typography fontWeight={600} fontSize="0.85rem" color={textSecondary}>
                          {formatDate(row.paymentDate)}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Chip
                          size="small"
                          label={row.paymentStatus || "PENDING"}
                          color={row.paymentStatus === "PAID" ? "success" : "warning"}
                          sx={{
                            fontWeight: 800,
                            fontSize: "0.7rem",
                            letterSpacing: "0.04em",
                            borderRadius: 2,
                          }}
                        />
                      </TableCell>
                      <TableCell align="right">
                        <Stack direction="row" spacing={0.5} justifyContent="flex-end">
                          <Button
                            size="small"
                            startIcon={<Visibility />}
                            onClick={() => downloadPdf(row)}
                            sx={{
                              fontWeight: 700,
                              fontSize: "0.75rem",
                              borderRadius: 2,
                              color: isDark ? "#93c5fd" : "#2563eb",
                              "&:hover": {
                                bgcolor: isDark ? "rgba(59, 130, 246, 0.12)" : "rgba(37, 99, 235, 0.08)",
                              },
                            }}
                          >
                            View
                          </Button>
                          <Button
                            size="small"
                            variant="contained"
                            startIcon={<Download />}
                            onClick={() => downloadPdf(row)}
                            sx={{
                              fontWeight: 700,
                              fontSize: "0.75rem",
                              borderRadius: 2,
                              background: "linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%)",
                              boxShadow: "0 4px 12px rgba(37, 99, 235, 0.3)",
                              "&:hover": {
                                background: "linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)",
                                boxShadow: "0 6px 16px rgba(37, 99, 235, 0.4)",
                              },
                            }}
                          >
                            PDF
                          </Button>
                        </Stack>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>
    </Box>
  );
}
