import React, { useEffect, useMemo, useState } from "react";
import {
  Alert,
  Avatar,
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Grid,
  IconButton,
  InputAdornment,
  LinearProgress,
  MenuItem,
  Paper,
  Select,
  Stack,
  Step,
  StepLabel,
  Stepper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
  useTheme,
} from "@mui/material";
import {
  AccountBalance,
  CalendarMonth,
  CheckCircle,
  Close,
  Download,
  Edit,
  Paid,
  PeopleAlt,
  PlayArrow,
  ReceiptLong,
  Search,
  Visibility,
  WarningAmber,
} from "@mui/icons-material";
import axiosInstance from "../utils/axiosConfig";

const months = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

const steps = ["Select Period", "Attendance", "Calculate", "Review", "Approve", "Payment", "Success", "Payslips & Report"];

const formatMoney = (value) =>
  `₹${Number(value || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 })}`;

const formatDate = (value) => {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "-";
  return date.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
};

const getName = (user) =>
  [user?.firstName, user?.lastName].filter(Boolean).join(" ").trim() || user?.email || "Employee";

const statusColor = (status) => {
  if (["PAID", "APPROVED", "CALCULATED", "RESOLVED"].includes(status)) return "success";
  if (["EXCEPTION", "MISSING_DATA", "FAILED"].includes(status)) return "error";
  if (["UNDER_REVIEW", "PAYMENT_PROCESSING", "PROCESSING"].includes(status)) return "info";
  return "warning";
};

function StatCard({ icon, label, value, tone = "blue" }) {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const colors = {
    blue: ["#3b82f6", isDark ? "rgba(59,130,246,0.14)" : "#eff6ff"],
    green: ["#22c55e", isDark ? "rgba(34,197,94,0.14)" : "#ecfdf5"],
    amber: ["#f59e0b", isDark ? "rgba(245,158,11,0.14)" : "#fffbeb"],
    slate: ["#94a3b8", isDark ? "rgba(148,163,184,0.12)" : "#f8fafc"],
  };
  const [main, bg] = colors[tone] || colors.blue;
  return (
    <Paper elevation={0} sx={{ p: 2, borderRadius: 2, bgcolor: bg, border: `1px solid ${isDark ? "rgba(255,255,255,0.08)" : "#e5e7eb"}` }}>
      <Stack direction="row" spacing={1.5} alignItems="center">
        <Avatar sx={{ bgcolor: main, color: "#fff", width: 42, height: 42 }}>{icon}</Avatar>
        <Box>
          <Typography variant="h6" fontWeight={900}>{value}</Typography>
          <Typography variant="body2" color="text.secondary" fontWeight={700}>{label}</Typography>
        </Box>
      </Stack>
    </Paper>
  );
}

export default function Payroll() {
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const border = isDark ? "rgba(255,255,255,0.08)" : "#e5e7eb";
  const bg = isDark ? "#0f172a" : "#ffffff";
  const softBg = isDark ? "rgba(15,23,42,0.72)" : "#f8fafc";

  const now = new Date();
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState("");
  const [overview, setOverview] = useState(null);
  const [runData, setRunData] = useState(null);
  const [activeStep, setActiveStep] = useState(0);
  const [month, setMonth] = useState(months[now.getMonth()]);
  const [year, setYear] = useState(now.getFullYear());
  const [payDate, setPayDate] = useState("");
  const [search, setSearch] = useState("");
  const [salaryRows, setSalaryRows] = useState([]);
  const [salaryOpen, setSalaryOpen] = useState(false);
  const [salaryForm, setSalaryForm] = useState({
    user: "",
    basicSalary: "",
    hra: "",
    allowance: "",
    incentive: "",
    pf: "",
    esi: "",
    professionalTax: "",
    tds: "",
    otherDeduction: "",
    overtimeHourlyRate: "",
    paymentMethod: "Bank Transfer",
    bankName: "",
    accountLast4: "",
  });
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [approveOpen, setApproveOpen] = useState(false);

  const payroll = runData?.payroll;
  const employees = runData?.employees || [];

  const loadOverview = async () => {
    setLoading(true);
    setError("");
    try {
      const { data } = await axiosInstance.get("/payroll/overview");
      setOverview(data.result);
      const current = data.result?.currentPeriod;
      if (current) {
        setMonth(current.month);
        setYear(current.year);
        setPayDate(current.payDate ? String(current.payDate).slice(0, 10) : "");
      }
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to load payroll overview.");
    } finally {
      setLoading(false);
    }
  };

  const loadSalaryStructures = async () => {
    try {
      const { data } = await axiosInstance.get("/payroll/salary-structures");
      setSalaryRows(data.result?.salaryStructures || []);
    } catch {
      setSalaryRows([]);
    }
  };

  useEffect(() => {
    loadOverview();
    loadSalaryStructures();
  }, []);

  const openSalarySetup = (row = null) => {
    const structure = row?.structure;
    const earnings = new Map((structure?.earnings || []).map((item) => [item.name, item.amount]));
    const deductions = new Map((structure?.deductions || []).map((item) => [item.name, item.amount]));
    setSalaryForm({
      user: row?.employee?._id || "",
      basicSalary: structure?.basicSalary || "",
      hra: earnings.get("HRA") || "",
      allowance: earnings.get("Allowance") || "",
      incentive: earnings.get("Incentive") || "",
      pf: deductions.get("PF") || "",
      esi: deductions.get("ESI") || "",
      professionalTax: deductions.get("Professional Tax") || "",
      tds: deductions.get("TDS") || "",
      otherDeduction: deductions.get("Other Deduction") || "",
      overtimeHourlyRate: structure?.overtimeHourlyRate || "",
      paymentMethod: structure?.paymentMethod || "Bank Transfer",
      bankName: structure?.bankName || "",
      accountLast4: structure?.accountLast4 || "",
    });
    setSalaryOpen(true);
  };

  const saveSalarySetup = async () => {
    setProcessing(true);
    setError("");
    try {
      await axiosInstance.post("/payroll/salary-structures", salaryForm);
      setSalaryOpen(false);
      await Promise.all([loadSalaryStructures(), loadOverview()]);
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to save employee salary.");
    } finally {
      setProcessing(false);
    }
  };

  const filteredEmployees = useMemo(() => {
    const term = search.trim().toLowerCase();
    if (!term) return employees;
    return employees.filter((row) =>
      `${getName(row.employee)} ${row.employee?.email || ""} ${row.department || ""} ${row.status || ""}`
        .toLowerCase()
        .includes(term)
    );
  }, [employees, search]);

  const currentStepFromStatus = (status) => {
    if (!status) return 0;
    if (status === "PAID") return 6;
    if (status === "PAYMENT_PROCESSING") return 5;
    if (status === "APPROVED") return 5;
    if (status === "EXCEPTION" || status === "UNDER_REVIEW") return 3;
    if (status === "CALCULATED") return 2;
    return 1;
  };

  const startPayroll = async () => {
    setProcessing(true);
    setError("");
    try {
      const { data } = await axiosInstance.post("/payroll/runs/start", {
        payrollMonth: month,
        payrollYear: Number(year),
        payDate,
      });
      setRunData(data.result);
      setActiveStep(currentStepFromStatus(data.result?.payroll?.status));
      await loadOverview();
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to start payroll.");
    } finally {
      setProcessing(false);
    }
  };

  const approvePayroll = async () => {
    if (!payroll?._id) return;
    setProcessing(true);
    setError("");
    try {
      const { data } = await axiosInstance.post(`/payroll/runs/${payroll._id}/approve`);
      setRunData(data.result);
      setActiveStep(5);
      setApproveOpen(false);
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to approve payroll.");
    } finally {
      setProcessing(false);
    }
  };

  const initiatePayment = async () => {
    if (!payroll?._id) return;
    setProcessing(true);
    setError("");
    try {
      await axiosInstance.post(`/payroll/runs/${payroll._id}/payment`, {
        paymentMethod: payroll.paymentMode || "Bank Transfer",
        paymentDate: payDate,
      });
      // Re-fetch the full payroll run so employee statuses update to PAID
      const { data: refreshed } = await axiosInstance.get(`/payroll/runs/${payroll._id}`);
      setRunData(refreshed.result);
      setActiveStep(6);
      await loadOverview();
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to initiate payment.");
    } finally {
      setProcessing(false);
    }
  };

  const openHistory = async (id) => {
    setProcessing(true);
    setError("");
    try {
      const { data } = await axiosInstance.get(`/payroll/runs/${id}`);
      setRunData(data.result);
      setActiveStep(currentStepFromStatus(data.result?.payroll?.status));
    } catch (err) {
      setError(err?.response?.data?.message || "Failed to open payroll.");
    } finally {
      setProcessing(false);
    }
  };

  const downloadReport = () => {
    const rows = [
      ["Employee", "Department", "Basic", "Allowances", "Gross", "Deductions", "Net Pay", "Status"],
      ...employees.map((row) => [
        getName(row.employee),
        row.department || "-",
        row.basicSalary,
        Number(row.allowances || 0) + Number(row.overtime || 0),
        row.grossSalary,
        row.totalDeductions,
        row.netSalary,
        row.status,
      ]),
    ];
    const csv = rows.map((row) => row.map((cell) => `"${String(cell ?? "").replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `payroll-${payroll?.payrollMonth || month}-${payroll?.payrollYear || year}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const pendingCritical = (payroll?.exceptions || []).filter((item) => item.severity === "CRITICAL" && item.status === "PENDING");

  return (
    <Box sx={{ p: { xs: 2, md: 3 }, bgcolor: theme.palette.background.default, minHeight: "100vh" }}>
      <Paper elevation={0} sx={{ p: 2.5, mb: 2.5, borderRadius: 2, bgcolor: bg, border: `1px solid ${border}` }}>
        <Stack direction={{ xs: "column", md: "row" }} justifyContent="space-between" spacing={2}>
          <Box>
            <Typography variant="h4" fontWeight={900}>Payroll</Typography>
            <Typography color="text.secondary">Monthly payroll processing, approval, payment tracking, payslips, and reports.</Typography>
          </Box>
          <Button variant="contained" startIcon={<PlayArrow />} onClick={() => setActiveStep(0)}>
            Process Payroll
          </Button>
        </Stack>
      </Paper>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {(loading || processing) && <LinearProgress sx={{ mb: 2 }} />}

      <Grid container spacing={2} sx={{ mb: 2.5 }}>
        <Grid item xs={12} md={3}>
          <StatCard icon={<PeopleAlt />} label="Total Employees" value={overview?.summary?.totalEmployees ?? "..."} />
        </Grid>
        <Grid item xs={12} md={3}>
          <StatCard icon={<CheckCircle />} label="Working Employees" value={overview?.summary?.workingEmployees ?? "..."} tone="green" />
        </Grid>
        <Grid item xs={12} md={3}>
          <StatCard icon={<Paid />} label="Estimated Payroll" value={formatMoney(overview?.summary?.estimatedPayroll)} tone="amber" />
        </Grid>
        <Grid item xs={12} md={3}>
          <StatCard icon={<ReceiptLong />} label="Pending Payroll" value={overview?.summary?.pendingPayroll ?? 0} tone="slate" />
        </Grid>
      </Grid>

      {!runData && (
        <Paper elevation={0} sx={{ p: 2.5, mb: 2.5, borderRadius: 2, bgcolor: bg, border: `1px solid ${border}` }}>
          <Stack direction={{ xs: "column", md: "row" }} justifyContent="space-between" spacing={2} mb={2}>
            <Box>
              <Typography variant="h6" fontWeight={900}>Salary Setup</Typography>
              <Typography color="text.secondary">
                First add each employee's monthly salary. Payroll will use this salary plus attendance to calculate net pay.
              </Typography>
            </Box>
            <Button variant="contained" startIcon={<Edit />} onClick={() => openSalarySetup()}>
              Add Employee Salary
            </Button>
          </Stack>

          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Employee</TableCell>
                  <TableCell>Basic Salary</TableCell>
                  <TableCell>Allowances</TableCell>
                  <TableCell>Deductions</TableCell>
                  <TableCell>Payment</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell align="right">Action</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {salaryRows.map((row) => {
                  const structure = row.structure;
                  const allowances = (structure?.earnings || []).reduce((sum, item) => sum + Number(item.amount || 0), 0);
                  const deductions = (structure?.deductions || []).reduce((sum, item) => sum + Number(item.amount || 0), 0);
                  return (
                    <TableRow key={row.employee?._id} hover>
                      <TableCell>
                        <Typography fontWeight={800}>{getName(row.employee)}</Typography>
                        <Typography variant="caption" color="text.secondary">{row.employee?.email}</Typography>
                      </TableCell>
                      <TableCell>{row.hasSalarySetup ? formatMoney(structure?.basicSalary) : "-"}</TableCell>
                      <TableCell>{row.hasSalarySetup ? formatMoney(allowances) : "-"}</TableCell>
                      <TableCell>{row.hasSalarySetup ? formatMoney(deductions) : "-"}</TableCell>
                      <TableCell>{structure?.paymentMethod || "-"}</TableCell>
                      <TableCell>
                        <Chip
                          size="small"
                          color={row.hasSalarySetup ? "success" : "warning"}
                          label={row.hasSalarySetup ? "Salary Set" : "Needs Salary"}
                        />
                      </TableCell>
                      <TableCell align="right">
                        <Button size="small" startIcon={<Edit />} onClick={() => openSalarySetup(row)}>
                          {row.hasSalarySetup ? "Edit" : "Add"}
                        </Button>
                      </TableCell>
                    </TableRow>
                  );
                })}
                {!salaryRows.length && (
                  <TableRow><TableCell colSpan={7} align="center">No employees found.</TableCell></TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      )}

      {!runData && (
        <Grid container spacing={2.5}>
          <Grid item xs={12} lg={4}>
            <Paper elevation={0} sx={{ p: 2.5, borderRadius: 2, bgcolor: bg, border: `1px solid ${border}` }}>
              <Typography variant="h6" fontWeight={900} mb={2}>Select Payroll Period</Typography>
              <Stack spacing={2}>
                <Select value={month} onChange={(e) => setMonth(e.target.value)} fullWidth>
                  {months.map((item) => <MenuItem key={item} value={item}>{item}</MenuItem>)}
                </Select>
                <TextField label="Payroll Year" value={year} onChange={(e) => setYear(e.target.value)} />
                <TextField label="Pay Date" type="date" value={payDate} onChange={(e) => setPayDate(e.target.value)} InputLabelProps={{ shrink: true }} />
                <Alert severity="info">System will automatically load employees, attendance, leave, salary structure, allowances, deductions, and overtime.</Alert>
                <Button variant="contained" size="large" onClick={startPayroll} disabled={processing}>
                  Start Payroll
                </Button>
              </Stack>
            </Paper>
          </Grid>
          <Grid item xs={12} lg={8}>
            <Paper elevation={0} sx={{ p: 2.5, borderRadius: 2, bgcolor: bg, border: `1px solid ${border}` }}>
              <Typography variant="h6" fontWeight={900} mb={2}>Recent Payrolls</Typography>
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Month</TableCell>
                      <TableCell>Employees</TableCell>
                      <TableCell>Net Payroll</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell align="right">Action</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {(overview?.history || []).map((row) => (
                      <TableRow key={row._id} hover>
                        <TableCell>{row.payrollMonth} {row.payrollYear}</TableCell>
                        <TableCell>{row.totalEmployees}</TableCell>
                        <TableCell>{formatMoney(row.netPayroll)}</TableCell>
                        <TableCell><Chip size="small" color={statusColor(row.status)} label={row.status} /></TableCell>
                        <TableCell align="right"><Button size="small" onClick={() => openHistory(row._id)}>View</Button></TableCell>
                      </TableRow>
                    ))}
                    {!overview?.history?.length && (
                      <TableRow><TableCell colSpan={5} align="center">No payroll history found.</TableCell></TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </Grid>
        </Grid>
      )}

      {runData && (
        <Stack spacing={2.5}>
          <Paper elevation={0} sx={{ p: 2.5, borderRadius: 2, bgcolor: bg, border: `1px solid ${border}` }}>
            <Stack direction={{ xs: "column", md: "row" }} justifyContent="space-between" spacing={2}>
              <Box>
                <Typography variant="h6" fontWeight={900}>{payroll.payrollMonth} {payroll.payrollYear}</Typography>
                <Typography color="text.secondary">
                  {formatDate(payroll.payPeriodStart)} - {formatDate(payroll.payPeriodEnd)} · Pay date {formatDate(payroll.payDate)}
                </Typography>
              </Box>
              <Stack direction="row" spacing={1}>
                <Chip color={statusColor(payroll.status)} label={payroll.status} />
                <Button variant="outlined" onClick={() => setRunData(null)}>Overview</Button>
              </Stack>
            </Stack>
            <Stepper activeStep={activeStep} alternativeLabel sx={{ mt: 3 }}>
              {steps.map((label) => <Step key={label}><StepLabel>{label}</StepLabel></Step>)}
            </Stepper>
          </Paper>

          <Grid container spacing={2}>
            <Grid item xs={12} md={3}><StatCard icon={<PeopleAlt />} label="Employees" value={payroll.totalEmployees} /></Grid>
            <Grid item xs={12} md={3}><StatCard icon={<Paid />} label="Gross Payroll" value={formatMoney(payroll.grossPayroll)} tone="green" /></Grid>
            <Grid item xs={12} md={3}><StatCard icon={<WarningAmber />} label="Deductions" value={formatMoney(payroll.totalDeductions)} tone="amber" /></Grid>
            <Grid item xs={12} md={3}><StatCard icon={<AccountBalance />} label="Net Payroll" value={formatMoney(payroll.netPayroll)} tone="slate" /></Grid>
          </Grid>

          {pendingCritical.length > 0 && (
            <Alert severity="error">
              {pendingCritical.length} critical exception(s) must be resolved before payroll approval.
            </Alert>
          )}

          <Paper elevation={0} sx={{ p: 2.5, borderRadius: 2, bgcolor: bg, border: `1px solid ${border}` }}>
            <Stack direction={{ xs: "column", md: "row" }} justifyContent="space-between" spacing={2} mb={2}>
              <Box>
                <Typography variant="h6" fontWeight={900}>Review Employee Payroll</Typography>
                <Typography color="text.secondary">Attendance, earnings, deductions, and net salary calculated from system records.</Typography>
              </Box>
              <TextField
                size="small"
                placeholder="Search employee"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                InputProps={{ startAdornment: <InputAdornment position="start"><Search /></InputAdornment> }}
              />
            </Stack>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Employee</TableCell>
                    <TableCell>Attendance</TableCell>
                    <TableCell>Basic</TableCell>
                    <TableCell>Allowances</TableCell>
                    <TableCell>Gross</TableCell>
                    <TableCell>Deductions</TableCell>
                    <TableCell>Net Pay</TableCell>
                    <TableCell>Status</TableCell>
                    <TableCell align="right">Action</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredEmployees.map((row) => (
                    <TableRow key={row._id} hover>
                      <TableCell>
                        <Typography fontWeight={800}>{getName(row.employee)}</Typography>
                        <Typography variant="caption" color="text.secondary">{row.employee?.email}</Typography>
                      </TableCell>
                      <TableCell>{row.attendance?.presentDays || 0} present · {row.attendance?.halfDays || 0} half</TableCell>
                      <TableCell>{formatMoney(row.basicSalary)}</TableCell>
                      <TableCell>{formatMoney(Number(row.allowances || 0) + Number(row.overtime || 0))}</TableCell>
                      <TableCell>{formatMoney(row.grossSalary)}</TableCell>
                      <TableCell>{formatMoney(row.totalDeductions)}</TableCell>
                      <TableCell><Typography fontWeight={900}>{formatMoney(row.netSalary)}</Typography></TableCell>
                      <TableCell><Chip size="small" color={statusColor(row.status)} label={row.status} /></TableCell>
                      <TableCell align="right">
                        <IconButton size="small" onClick={() => setSelectedEmployee(row)}><Visibility fontSize="small" /></IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>

          <Paper elevation={0} sx={{ p: 2.5, borderRadius: 2, bgcolor: bg, border: `1px solid ${border}` }}>
            <Typography variant="h6" fontWeight={900} mb={1}>Exception Report</Typography>
            {(payroll.exceptions || []).length ? (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow><TableCell>Problem</TableCell><TableCell>Action</TableCell><TableCell>Severity</TableCell><TableCell>Status</TableCell></TableRow>
                  </TableHead>
                  <TableBody>
                    {payroll.exceptions.map((item, index) => (
                      <TableRow key={`${item.problem}-${index}`}>
                        <TableCell>{item.problem}</TableCell>
                        <TableCell>{item.action}</TableCell>
                        <TableCell><Chip size="small" color={item.severity === "CRITICAL" ? "error" : "warning"} label={item.severity} /></TableCell>
                        <TableCell>{item.status}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            ) : (
              <Alert severity="success">No payroll exceptions found. Payroll is ready for approval.</Alert>
            )}
          </Paper>

          <Paper elevation={0} sx={{ p: 2.5, borderRadius: 2, bgcolor: softBg, border: `1px solid ${border}` }}>
            <Stack direction={{ xs: "column", md: "row" }} justifyContent="space-between" spacing={2}>
              <Box>
                <Typography variant="h6" fontWeight={900}>Next Action</Typography>
                <Typography color="text.secondary">
                  Approve only after attendance, salary calculation, deductions, and exceptions have been reviewed.
                </Typography>
              </Box>
              <Stack direction="row" spacing={1}>
                <Button variant="outlined" startIcon={<Download />} onClick={downloadReport}>Download Report</Button>
                {payroll.status === "APPROVED" ? (
                  <Button variant="contained" startIcon={<Paid />} onClick={initiatePayment} disabled={processing}>Initiate Payment</Button>
                ) : payroll.status === "PAID" ? (
                  <Button variant="contained" color="success" startIcon={<CheckCircle />} onClick={downloadReport}>Payment Successful</Button>
                ) : (
                  <Button variant="contained" startIcon={<CheckCircle />} onClick={() => setApproveOpen(true)} disabled={pendingCritical.length > 0 || processing}>
                    Approve Payroll
                  </Button>
                )}
              </Stack>
            </Stack>
          </Paper>
        </Stack>
      )}

      <Dialog open={salaryOpen} onClose={() => setSalaryOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>
          <Stack direction="row" justifyContent="space-between" alignItems="center">
            <Box>
              <Typography variant="h6" fontWeight={900}>Employee Salary Setup</Typography>
              <Typography variant="body2" color="text.secondary">This monthly salary structure is used when payroll is calculated.</Typography>
            </Box>
            <IconButton onClick={() => setSalaryOpen(false)}><Close /></IconButton>
          </Stack>
        </DialogTitle>
        <DialogContent dividers>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <Typography fontWeight={900} mb={1}>Employee</Typography>
              <Select
                fullWidth
                value={salaryForm.user}
                onChange={(e) => setSalaryForm((prev) => ({ ...prev, user: e.target.value }))}
                displayEmpty
              >
                <MenuItem value="" disabled>Select employee</MenuItem>
                {salaryRows.map((row) => (
                  <MenuItem key={row.employee?._id} value={row.employee?._id}>
                    {getName(row.employee)} - {row.employee?.email}
                  </MenuItem>
                ))}
              </Select>
            </Grid>

            <Grid item xs={12}>
              <Alert severity="info">Simple flow: set Basic Salary, add monthly allowances/deductions, then click Save. After this, use Start Payroll.</Alert>
            </Grid>

            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Basic Salary" type="number" value={salaryForm.basicSalary} onChange={(e) => setSalaryForm((p) => ({ ...p, basicSalary: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="HRA" type="number" value={salaryForm.hra} onChange={(e) => setSalaryForm((p) => ({ ...p, hra: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Other Allowance" type="number" value={salaryForm.allowance} onChange={(e) => setSalaryForm((p) => ({ ...p, allowance: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Incentive" type="number" value={salaryForm.incentive} onChange={(e) => setSalaryForm((p) => ({ ...p, incentive: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Overtime Hourly Rate" type="number" value={salaryForm.overtimeHourlyRate} onChange={(e) => setSalaryForm((p) => ({ ...p, overtimeHourlyRate: e.target.value }))} />
            </Grid>

            <Grid item xs={12}>
              <Divider sx={{ my: 1 }} />
              <Typography fontWeight={900}>Deductions</Typography>
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="PF" type="number" value={salaryForm.pf} onChange={(e) => setSalaryForm((p) => ({ ...p, pf: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="ESI" type="number" value={salaryForm.esi} onChange={(e) => setSalaryForm((p) => ({ ...p, esi: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Professional Tax" type="number" value={salaryForm.professionalTax} onChange={(e) => setSalaryForm((p) => ({ ...p, professionalTax: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="TDS" type="number" value={salaryForm.tds} onChange={(e) => setSalaryForm((p) => ({ ...p, tds: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Other Deduction" type="number" value={salaryForm.otherDeduction} onChange={(e) => setSalaryForm((p) => ({ ...p, otherDeduction: e.target.value }))} />
            </Grid>

            <Grid item xs={12}>
              <Divider sx={{ my: 1 }} />
              <Typography fontWeight={900}>Payment Details</Typography>
            </Grid>
            <Grid item xs={12} md={4}>
              <Select fullWidth value={salaryForm.paymentMethod} onChange={(e) => setSalaryForm((p) => ({ ...p, paymentMethod: e.target.value }))}>
                <MenuItem value="Bank Transfer">Bank Transfer</MenuItem>
                <MenuItem value="NEFT / RTGS">NEFT / RTGS</MenuItem>
                <MenuItem value="UPI">UPI</MenuItem>
                <MenuItem value="Cheque">Cheque</MenuItem>
                <MenuItem value="Cash">Cash</MenuItem>
              </Select>
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Bank Name" value={salaryForm.bankName} onChange={(e) => setSalaryForm((p) => ({ ...p, bankName: e.target.value }))} />
            </Grid>
            <Grid item xs={12} md={4}>
              <TextField fullWidth label="Account Last 4 Digits" value={salaryForm.accountLast4} onChange={(e) => setSalaryForm((p) => ({ ...p, accountLast4: e.target.value }))} />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSalaryOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={saveSalarySetup} disabled={!salaryForm.user || !salaryForm.basicSalary || processing}>
            Save Salary
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={Boolean(selectedEmployee)} onClose={() => setSelectedEmployee(null)} maxWidth="md" fullWidth>
        {selectedEmployee && (
          <>
            <DialogTitle>
              <Stack direction="row" justifyContent="space-between" alignItems="center">
                <Box>
                  <Typography variant="h6" fontWeight={900}>{getName(selectedEmployee.employee)}</Typography>
                  <Typography variant="body2" color="text.secondary">Salary calculation details</Typography>
                </Box>
                <IconButton onClick={() => setSelectedEmployee(null)}><Close /></IconButton>
              </Stack>
            </DialogTitle>
            <DialogContent dividers>
              <Grid container spacing={2}>
                <Grid item xs={12} md={6}>
                  <Paper elevation={0} sx={{ p: 2, border: `1px solid ${border}`, borderRadius: 2 }}>
                    <Typography fontWeight={900} mb={1}>Attendance</Typography>
                    {[
                      ["Working Days", selectedEmployee.attendance?.workingDays],
                      ["Present", selectedEmployee.attendance?.presentDays],
                      ["Paid Leave", selectedEmployee.attendance?.paidLeave],
                      ["Unpaid Leave", selectedEmployee.attendance?.unpaidLeave],
                      ["Half Days", selectedEmployee.attendance?.halfDays],
                      ["Overtime", `${selectedEmployee.attendance?.overtimeHours || 0} hrs`],
                    ].map(([label, value]) => (
                      <Stack key={label} direction="row" justifyContent="space-between" py={0.6}>
                        <Typography color="text.secondary">{label}</Typography><Typography fontWeight={800}>{value || 0}</Typography>
                      </Stack>
                    ))}
                  </Paper>
                </Grid>
                <Grid item xs={12} md={6}>
                  <Paper elevation={0} sx={{ p: 2, border: `1px solid ${border}`, borderRadius: 2 }}>
                    <Typography fontWeight={900} mb={1}>Final Salary</Typography>
                    <Stack direction="row" justifyContent="space-between" py={0.6}><Typography>Gross Salary</Typography><Typography fontWeight={900}>{formatMoney(selectedEmployee.grossSalary)}</Typography></Stack>
                    <Stack direction="row" justifyContent="space-between" py={0.6}><Typography>Total Deduction</Typography><Typography fontWeight={900}>{formatMoney(selectedEmployee.totalDeductions)}</Typography></Stack>
                    <Divider sx={{ my: 1 }} />
                    <Stack direction="row" justifyContent="space-between" py={0.6}><Typography fontWeight={900}>Net Salary</Typography><Typography fontWeight={900}>{formatMoney(selectedEmployee.netSalary)}</Typography></Stack>
                  </Paper>
                </Grid>
                <Grid item xs={12} md={6}>
                  <Typography fontWeight={900} mb={1}>Earnings</Typography>
                  <Table size="small">
                    <TableBody>
                      <TableRow><TableCell>Basic Salary</TableCell><TableCell align="right">{formatMoney(selectedEmployee.basicSalary)}</TableCell></TableRow>
                      {(selectedEmployee.earnings || []).map((item) => (
                        <TableRow key={item.name}><TableCell>{item.name}</TableCell><TableCell align="right">{formatMoney(item.amount)}</TableCell></TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </Grid>
                <Grid item xs={12} md={6}>
                  <Typography fontWeight={900} mb={1}>Deductions</Typography>
                  <Table size="small">
                    <TableBody>
                      {(selectedEmployee.deductions || []).map((item) => (
                        <TableRow key={item.name}><TableCell>{item.name}</TableCell><TableCell align="right">{formatMoney(item.amount)}</TableCell></TableRow>
                      ))}
                      {!selectedEmployee.deductions?.length && <TableRow><TableCell colSpan={2}>No deductions.</TableCell></TableRow>}
                    </TableBody>
                  </Table>
                </Grid>
              </Grid>
            </DialogContent>
          </>
        )}
      </Dialog>

      <Dialog open={approveOpen} onClose={() => setApproveOpen(false)} maxWidth="xs" fullWidth>
        <DialogTitle>Approve Payroll?</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to approve payroll for {payroll?.payrollMonth} {payroll?.payrollYear}? After approval, payroll will be locked and payment can be initiated.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setApproveOpen(false)}>Cancel</Button>
          <Button variant="contained" onClick={approvePayroll} disabled={processing}>Approve Payroll</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}
